pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the candidate newOwner address; the admin (deployer) will call setOwner
    function testFuzz_property(address newOwner) public {
        // keep domain wide but exclude zero address only if desired; zero is admissible here
        // ensure the call is made by the admin (the deployer in setUp)
        // deployer is address(this) in setUp context? In Foundry, setUp is run from this contract, so the admin is address(this).
        // We must call setOwner as admin. Use vm.prank to impersonate the admin (this contract) explicitly.

        // call setOwner as admin
        vm.prank(address(this));
        bool ok;
        try c.setOwner(newOwner) returns (bool success) { ok = success; } catch { ok = false; }

        // After the call completes, the reference implementation always sets owner() == newOwner.
        // Mutant that assigns to admin instead will in some cases leave owner unchanged, so the equality may fail.
        assertTrue(c.owner() == newOwner == ok);
    }
}

