pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: address adminActor is the caller who is admin and will invoke setOwner;
    // address newOwner is the candidate owner to set; both are fuzzed so fuzzer can find failing case
    function testFuzz_property(address adminActor, address newOwner) public {
        // keep addresses wide but avoid zero-address for clarity (still admissible broadly)
        vm.assume(adminActor != address(0));
        vm.assume(newOwner != address(0));

        // The contract's constructor set msg.sender as both admin (private) and owner (public).
        // But only the original deployer (address that deployed c in setUp) is admin. We must make
        // adminActor be that deployer to satisfy onlyAdmin check. The deployer in setUp is this test
        // contract's address (address(this)). So require fuzzed adminActor equals address(this).
        // Instead of constraining the fuzzer away, we will simulate the admin call by using the
        // actual admin (this test contract). Thus we still fuzz newOwner for distinguishing behavior.

        // Drive the call as the admin (this contract is the admin because it deployed c in setUp())
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): after admin calls setOwner(newOwner), owner() equals newOwner.
        // The reference contract satisfies this for all inputs; the mutant that removed the assignment
        // will keep the old owner and thus for some newOwner values this assertion will fail.
        assertTrue(ok && (c.owner() == newOwner));
    }
}

