pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an address representing the new owner value the admin will provide.
    // The fuzzer will try many addresses; the property is that after setOwner by admin,
    // c.owner() must equal the provided _owner argument for the correct contract.
    function testFuzz_property(address newOwner) public {
        // Keep the domain wide but avoid the zero-address triviality if desired
        vm.assume(newOwner != address(0));

        // The deployer (this contract) is the admin because C's constructor set admin = msg.sender in setUp()
        // Use vm.prank to make the call as the admin (the contract that deployed C is this test contract)
        vm.startPrank(address(this));
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The reference implementation always sets owner to the provided argument when called by admin.
        // So after a successful call, c.owner() must equal newOwner.
        // This single assertion is true for the reference and false for the mutant that sets owner = tx.origin.
        // We assert that either the call reverted (not expected) or the owner equals the argument; however,
        // to keep a single assertTrue reading c's public surface, assert that if the call succeeded (ok==true)
        // then c.owner() == newOwner. We encode that as: ok implies owner == newOwner.
        // Equivalent boolean: !ok || (c.owner() == newOwner)
        assertTrue(!ok || c.owner() == newOwner);
    }
}

