pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // fuzzer will supply caller (actor) and the newOwner candidate
    function setUp() public { c = new C(); }

    // General rule: only the original deployer (admin) can successfully call setOwner.
    // We fuzz caller and candidate newOwner. For the reference contract, any caller
    // different from the deployer (address(this) is deployer) will NOT be able to
    // change owner (the call will revert), so owner remains as initially set.
    // The mutant permits the current owner to call setOwner; if we pick a caller
    // equal to the initial owner, the mutant will allow the change while the
    // reference only allows the deployer—thus the property distinguishes them.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid the zero address for clarity (still wide)
        // Allow caller==address(0) because EOAs may be zero; it's fine. No tight bounds.

        // initial deployer/admin and initial owner are both the test contract deployer (address(this) at deployment of C)
        address deployer = address(this);

        // Ensure newOwner is not meaningless: allow any address (including zero) — wide domain

        // We want to test behavior when CALLER is not the deployer but IS the initial owner.
        // In the reference, only deployer can call setOwner. The mutant allows current owner
        // to call setOwner. To trigger the difference we let caller equal the initial owner
        // while caller != deployer. Since initial owner == deployer in setup, we must first
        // change owner using the deployer so that owner != deployer, then have that owner try to setOwner again.

        // 1) As deployer (this contract), setOwner to 'caller' so that owner becomes caller.
        bool ok;
        try c.setOwner(caller) { ok = true; } catch { ok = false; }
        // In the reference, deployer (this) is admin so this must succeed for all inputs.
        // Assert that this succeeded to ensure we have owner==caller in both versions before step 2.
        assertTrue(ok, "initial setOwner by deployer must succeed");

        // 2) Now have 'caller' attempt to call setOwner(newOwner).
        // In the reference, only the original deployer can call setOwner, so this should revert unless caller==deployer.
        vm.prank(caller);
        bool ok2;
        try c.setOwner(newOwner) { ok2 = true; } catch { ok2 = false; }

        // SINGLE assertion: For the correct contract, if the caller is not the original deployer,
        // their attempt to call setOwner must fail, i.e., ok2 == false when caller != deployer.
        // This is universally true for all inputs in the reference, but the mutant (which checks msg.sender==owner)
        // will allow this call when caller equals the current owner, producing ok2 == true for some inputs.
        if (caller != deployer) {
            assertTrue(!ok2);
        } else {
            // If caller == deployer, the call should succeed in both versions.
            assertTrue(ok2);
        }
    }
}

