import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary address to set as the new owner.
    function testFuzz_property(address newOwner) public {
        // keep wide domain but avoid zero-address only if desired; allow zero address as admissible too
        // The admin is the deployer (this contract in setUp). Only admin can call setOwner.
        // Call setOwner from admin (this contract). We capture the returned boolean via try/catch
        bool ok = false;
        try c.setOwner(newOwner) returns (bool r) {
            // record the returned value
            ok = r;
        } catch {
            // if it reverts, ok remains false; however reference does not revert for any input when called by admin
            ok = false;
        }

        // The universal property: for any fuzzed newOwner, the reference contract's setOwner returns true.
        // The mutant that returns false after setting owner will make this assertion fail for some input(s).
        assertTrue(ok);
    }
}

