    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an arbitrary address that the fuzzer will supply as the caller trying to call setOwner
    function testFuzz_property(address caller) public {
        // avoid the trivial case where caller is the deployer/admin (which is address(this) in setUp)
        // keep domain wide but exclude the known admin so we can detect difference
        vm.assume(caller != address(this));

        // try calling setOwner as the fuzzed caller and record whether it completes or reverts
        bool ok;
        vm.prank(caller);
        try c.setOwner(caller) returns (bool res) {
            ok = res; // if it returns, record the returned boolean
        } catch {
            ok = false; // treat revert as failure
        }

        // The reference implementation requires onlyAdmin, so for any caller != admin the call must revert
        // Thus ok must be false for all such callers. The mutant that removes the check will allow some
        // non-admin callers to succeed (ok == true). We assert the reference property: ok == false.
        assertTrue(ok == false);
    }
}

