pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: caller address that will attempt to set owner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses non-zero to be meaningful
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // Ensure caller is NOT the admin (deployer). The admin is the test contract deployer of C, i.e., address(this)
        // We want to test that only admin can change owner: for any caller != admin, calling setOwner must NOT succeed in changing owner on the reference.
        vm.assume(caller != address(this));

        // Record original owner
        address originalOwner = c.owner();

        // Have the fuzzed caller attempt to call setOwner
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: on the reference (correct) contract, non-admin callers must NOT be able to change owner.
        // So regardless of whether the call reverted or returned, the public getter owner() must remain equal to originalOwner.
        assertTrue(c.owner() == originalOwner);
    }
}
